-- Ian partner seller - January 2026 historical orders (from FINEST HEALTH ORDERS.xlsx / JANUARY 2026)
-- 6444 shipped parcels - ship_date = section Pickup Date
-- Run on production: mysql -u USER -p rts_system < sql/seed_ian_january_2026_partner_orders.sql
--
-- Replaces prior Ian Jan-2026 import that used ship_date=2026-01-31 for every row.
-- Safe if re-run: deletes that batch, then inserts (skips any other existing tracking).

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DELETE FROM online_order_parcels
WHERE partner_seller = 'ian'
  AND status = 'shipped'
  AND csr_batch_id IS NULL
  AND ship_date = '2026-01-31'
  AND created_at = '2026-01-31 12:00:00';

-- Also clear any prior pickup-dated Ian Jan rows from this seed (re-run safe).
DELETE FROM online_order_parcels
WHERE partner_seller = 'ian'
  AND status = 'shipped'
  AND csr_batch_id IS NULL
  AND ship_date BETWEEN '2026-01-01' AND '2026-01-31'
  AND created_at LIKE '2026-01-% 12:00:00';

INSERT INTO online_order_parcels (
  tracking_number, items_raw, items_parsed_json, recipient_name, courier, order_no,
  source_pipeline, partner_seller, status, ship_date, created_at
)
SELECT * FROM (
SELECT '1069671190519872' AS tracking_number, '1 Black Rice Coffee' AS items_raw, '{"deltas":[],"other_items":[{"label":"Black Rice Coffee","qty":1,"raw":"1 Black Rice Coffee","product_key":"brc"}]}' AS items_parsed_json, 'Virgilio Mindo' AS recipient_name, 'Lazada-PH-Flash Express PH' AS courier, '1069671190519872' AS order_no, 'partner' AS source_pipeline, 'ian' AS partner_seller, 'shipped' AS status, '2026-01-02' AS ship_date, '2026-01-02 12:00:00' AS created_at
UNION ALL
